import type { AudioTrackInfo } from "../../core/types.js";

interface AudioTrackLike {
  readonly id?: string;
  readonly label?: string;
  readonly language?: string;
  enabled: boolean;
}

type MediaWithAudioTracks = HTMLMediaElement & {
  readonly audioTracks?: {
    readonly length: number;
    readonly [index: number]: AudioTrackLike | undefined;
  };
};

/** Reads the audio tracks exposed by a media element. */
export function toAudioTrackInfos(media: HTMLMediaElement): readonly AudioTrackInfo[] {
  const tracks: AudioTrackInfo[] = [];
  const audioTracks = (media as MediaWithAudioTracks).audioTracks;

  if (audioTracks === undefined) {
    return tracks;
  }

  for (let index = 0; index < audioTracks.length; index += 1) {
    const track = audioTracks[index];

    if (track === undefined) {
      continue;
    }

    tracks.push({
      id: track.id ?? `audio-${index}`,
      label: track.label ?? `Track ${index + 1}`,
      language: track.language ?? "",
      default: track.enabled,
    });
  }

  return tracks;
}

/** Enables one audio track and disables the rest. */
export function selectAudioTrack(media: HTMLMediaElement, id: string | null): void {
  const audioTracks = (media as MediaWithAudioTracks).audioTracks;

  if (audioTracks === undefined) {
    return;
  }

  for (let index = 0; index < audioTracks.length; index += 1) {
    const track = audioTracks[index];

    if (track !== undefined) {
      track.enabled = track.id === id;
    }
  }
}
